/**
 * fuchsian2.js — exact tests at the real place for Γ = ⟨g₁, g₂⟩ ⊂ PGL₂(ℚ), through the
 * orientation-preserving subgroup Γ⁺ when it is generated by two elements A, B:
 *   · Γ⁺ = Γ when both determinants are positive;
 *   · Γ⁺ = ⟨g₁, g₂g₁g₂⁻¹⟩ when g₂ (det < 0) is an involution (trace 0);
 *   · Γ⁺ = ⟨g₂g₁, g₁g₂⟩ when both determinants are negative and one generator is an involution.
 * With κ = tr[A, B] (normalized, exact):
 *   discrete  — κ ≤ −2 (Fricke: a one-holed or punctured torus group, discrete and free), or A, B
 *               parabolic with |tr(AB) − 2| ≥ 4 (traces normalized to +2; conjugate to
 *               ⟨(1 a; 0 1), (1 0; b 1)⟩ with |ab| ≥ 4: discrete and free);
 *   not discrete — −2 < κ < 2 with κ ∉ {0, ±1}: the commutator is elliptic of infinite order.
 * Also: a generator (or an element of Γ⁺ among A, B, AB, AB⁻¹) elliptic of infinite order (not
 * discrete), and a parabolic with an involution (Hecke's criterion).
 * Returns { status: 'discrete' | 'nondiscrete', reason } or null.
 */
const babs = (x) => (x < 0n ? -x : x);
const bgcd = (a, b) => { a = babs(a); b = babs(b); while (b) [a, b] = [b, a % b]; return a; };
const mul = (A, B) => [A[0] * B[0] + A[1] * B[2], A[0] * B[1] + A[1] * B[3], A[2] * B[0] + A[3] * B[2], A[2] * B[1] + A[3] * B[3]];
const adj = (A) => [A[3], -A[1], -A[2], A[0]];
const det = (A) => A[0] * A[3] - A[1] * A[2];
const tr = (A) => A[0] + A[3];
const isqrt = (n) => { if (n < 2n) return n; let x = BigInt(Math.floor(Math.sqrt(Number(n)))); while (x * x > n) x--; while ((x + 1n) * (x + 1n) <= n) x++; return x; };

/** rational p/q (q > 0) as [p, q] reduced */
const frac = (p, q) => { if (q < 0n) { p = -p; q = -q; } const g = bgcd(p, q) || 1n; return [p / g, q / g]; };
const cmp = ([a, b], [c, d]) => (a * d < c * b ? -1 : a * d > c * b ? 1 : 0);

function primitive(row) {
    const q = row.map((e) => /^\s*(-?\d+)\s*(?:\/\s*(\d+))?\s*$/.exec(String(e)));
    if (q.some((x) => !x)) return null;
    const num = q.map((x) => BigInt(x[1])), den = q.map((x) => BigInt(x[2] || '1'));
    const L = den.reduce((l, d) => (l / bgcd(l, d)) * d, 1n);
    const m = num.map((n, i) => n * (L / den[i]));
    const g = m.reduce((s, x) => bgcd(s, x), 0n);
    return m.map((x) => x / g);
}

function plusPair(g1, g2) {
    const d1 = det(g1), d2 = det(g2);
    if (d1 > 0n && d2 > 0n) return [g1, g2];
    if (d1 < 0n && d2 > 0n) [g1, g2] = [g2, g1];
    if (det(g1) > 0n && det(g2) < 0n) return tr(g2) === 0n ? [g1, mul(mul(g2, g1), adj(g2))] : null;
    if (tr(g1) === 0n) return [mul(g2, g1), mul(g1, g2)];
    if (tr(g2) === 0n) return [mul(g1, g2), mul(g2, g1)];
    return null;
}

/** an orientation-preserving element that is elliptic of infinite order: τ = tr²/det ∈ (0, 4) ∖ {1, 2, 3} */
function ellipticInfinite(X) {
    const d = det(X);
    if (d <= 0n) return false;
    const t2 = tr(X) * tr(X);
    if (t2 >= 4n * d || t2 === 0n) return false;
    return ![1n, 2n, 3n].some((k) => t2 === k * d);
}

export function fuchsianPairTest(rows) {
    if (rows.length !== 2) return null;
    const g = rows.map(primitive);
    if (g.some((m) => !m || det(m) === 0n)) return null;
    for (const [i, X] of g.entries()) if (ellipticInfinite(X)) return { status: 'nondiscrete', reason: `g${i + 1} is elliptic of infinite order (tr²/det = ${tr(X) * tr(X)}/${det(X)})` };
    const P = plusPair(g[0], g[1]);
    if (!P) return null;
    const [A, B] = P;
    for (const X of [A, B, mul(A, B), mul(A, adj(B))]) if (ellipticInfinite(X)) return { status: 'nondiscrete', reason: `Γ⁺ contains an elliptic of infinite order (tr²/det = ${tr(X) * tr(X)}/${det(X)})` };
    // a parabolic and an involution: Hecke, ⟨(1 λ; 0 1), (0 −1; 1 0)⟩ with λ = |tr(PE)| (normalized),
    // discrete iff λ ≥ 2 or λ = 2cos(π/q) — over ℚ, λ² ∈ {1, 2, 3}
    const parab = (X) => tr(X) * tr(X) === 4n * det(X) && det(X) > 0n;
    const invol = (X) => tr(X) === 0n && det(X) > 0n;
    for (const [Pp, E] of [[A, B], [B, A]]) {
        if (!parab(Pp) || !invol(E)) continue;
        const num = tr(mul(Pp, E)) ** 2n, den = det(Pp) * det(E);           // λ² = num/den
        if (num >= 4n * den) return { status: 'discrete', reason: `Γ⁺ is generated by a parabolic and an involution, conjugate to ⟨(1 λ; 0 1), (0 −1; 1 0)⟩ with λ² = ${frac(num, den).join('/')} ≥ 4 (Hecke): discrete, ℤ ∗ ℤ/2` };
        if ([1n, 2n, 3n].some((k) => num === k * den)) return { status: 'discrete', reason: `Γ⁺ is generated by a parabolic and an involution, conjugate to the Hecke group with λ = 2cos(π/q), λ² = ${num / den}: discrete` };
        if (num !== 0n) return { status: 'nondiscrete', reason: `Γ⁺ is generated by a parabolic and an involution with λ² = ${frac(num, den).join('/')} < 4, not 2cos²(π/q)·4: not discrete (Hecke)` };
    }
    const kappa = frac(tr(mul(mul(A, B), mul(adj(A), adj(B)))), det(A) * det(B));
    const kTxt = `${kappa[0]}${kappa[1] === 1n ? '' : '/' + kappa[1]}`;
    if (cmp(kappa, [2n, 1n]) === 0) return null;                       // elementary
    if (cmp(kappa, [-2n, 1n]) <= 0) return { status: 'discrete', reason: `Γ⁺ = ⟨A, B⟩ with tr[A, B] = ${kTxt} ≤ −2: discrete and free (Fricke)` };
    const parabolic = (X) => tr(X) * tr(X) === 4n * det(X);
    if (parabolic(A) && parabolic(B)) {
        const D = det(A) * det(B), r = isqrt(D);
        if (r * r === D) {
            const s = (tr(A) > 0n ? 1n : -1n) * (tr(B) > 0n ? 1n : -1n);
            const t = frac(s * tr(mul(A, B)), r);                          // normalized tr(AB) = 2 + ab
            const ab = frac(t[0] - 2n * t[1], t[1]);
            if (cmp([babs(ab[0]), ab[1]], [4n, 1n]) >= 0) return { status: 'discrete', reason: `Γ⁺ is generated by two parabolics conjugate to (1 a; 0 1), (1 0; b 1) with |ab| = ${babs(ab[0])}${ab[1] === 1n ? '' : '/' + ab[1]} ≥ 4: discrete and free` };
        }
    }
    if (cmp(kappa, [-2n, 1n]) > 0 && cmp(kappa, [2n, 1n]) < 0 && ![0n, 1n, -1n].some((v) => cmp(kappa, [v, 1n]) === 0)) {
        return { status: 'nondiscrete', reason: `the commutator of Γ⁺'s generators has trace ${kTxt}, strictly between −2 and 2 and not 0 or ±1: an elliptic of infinite order` };
    }
    return null;
}
